// Package workerpool provides a bounded worker pool with context cancellation,
// task submission with backpressure, panic recovery, graceful shutdown, and
// deterministic result delivery.
//
// Public API:
//
//   - NewPool(capacity int, workers int) *Pool
//     Creates a new pool with the given queue capacity and number of workers.
//     capacity must be >= 0; workers must be >= 1.
//
//   - (*Pool).Submit(ctx context.Context, task func() (interface{}, error)) error
//     Submits a task to the pool. If the queue is full, it blocks until space
//     is available or ctx is canceled. Returns an error if the pool is closed
//     or ctx is canceled before the task is enqueued.
//
//   - (*Pool).Wait(ctx context.Context) error
//     Blocks until all submitted tasks have completed or ctx is canceled.
//     Returns an error if ctx is canceled.
//
//   - (*Pool).Close()
//     Initiates graceful shutdown. No new tasks can be submitted after Close
//     is called. Existing tasks in the queue will still be processed.
//     Close is idempotent.
//
//   - (*Pool).Shutdown(ctx context.Context) error
//     Like Close but also waits for all in-flight tasks to complete, respecting
//     ctx cancellation. Returns an error if ctx is canceled before all tasks
//     finish.
//
// Concurrency invariants:
//   - At most `workers` goroutines execute tasks concurrently.
//   - The queue holds at most `capacity` pending tasks.
//   - Panics in tasks are recovered and converted to errors.
//   - No goroutine leaks: all worker goroutines exit after Close/Shutdown.
//   - No data races: all shared state is protected by mutexes or channels.
package workerpool

import (
	"context"
	"errors"
	"fmt"
	"sync"
)

// ErrPoolClosed is returned when submitting to a closed pool.
var ErrPoolClosed = errors.New("workerpool: pool is closed")

// ErrPoolShutdown is returned when the pool is shutting down and cannot accept new tasks.
var ErrPoolShutdown = errors.New("workerpool: pool is shutting down")

// task represents a unit of work to be executed by a worker.
type task struct {
	fn     func() (interface{}, error)
	result chan<- taskResult
}

// taskResult holds the outcome of a task execution.
type taskResult struct {
	value interface{}
	err   error
}

// Pool is a bounded worker pool.
type Pool struct {
	capacity int
	workers  int

	queue      chan task
	closed     bool
	closedMu   sync.Mutex
	closedCh   chan struct{} // closed when Close() is called
	shutdownCh chan struct{} // closed when Shutdown() completes

	wg sync.WaitGroup // tracks active workers

	// For deterministic result delivery: each Submit returns a channel that
	// receives the result once the task completes.
	// We use a per-task result channel embedded in the task struct.
}

// NewPool creates a new worker pool.
// capacity: maximum number of pending tasks in the queue (>= 0).
// workers: number of worker goroutines (>= 1).
// Panics if workers < 1.
func NewPool(capacity int, workers int) *Pool {
	if workers < 1 {
		panic("workerpool: workers must be >= 1")
	}
	if capacity < 0 {
		capacity = 0
	}

	p := &Pool{
		capacity:   capacity,
		workers:    workers,
		queue:      make(chan task, capacity),
		closedCh:   make(chan struct{}),
		shutdownCh: make(chan struct{}),
	}

	// Start workers
	for i := 0; i < workers; i++ {
		p.wg.Add(1)
		go p.worker()
	}

	return p
}

// worker is the main loop for each worker goroutine.
func (p *Pool) worker() {
	defer p.wg.Done()

	for {
		select {
		case <-p.closedCh:
			// Drain remaining tasks in the queue before exiting.
			// This ensures graceful shutdown: all enqueued tasks are processed.
			for {
				select {
				case t := <-p.queue:
					p.executeTask(t)
				default:
					return
				}
			}
		case t := <-p.queue:
			p.executeTask(t)
		}
	}
}

// executeTask runs a task and sends the result to the task's result channel.
// Panics are recovered and converted to errors.
func (p *Pool) executeTask(t task) {
	defer func() {
		if r := recover(); r != nil {
			t.result <- taskResult{
				value: nil,
				err:   fmt.Errorf("panic in task: %v", r),
			}
		}
	}()

	value, err := t.fn()
	t.result <- taskResult{value: value, err: err}
}

// Submit submits a task to the pool.
// If the queue is full, it blocks until space is available or ctx is canceled.
// Returns ErrPoolClosed if the pool is closed.
// Returns ctx.Err() if ctx is canceled before the task is enqueued.
func (p *Pool) Submit(ctx context.Context, fn func() (interface{}, error)) error {
	if fn == nil {
		return errors.New("workerpool: task function is nil")
	}

	p.closedMu.Lock()
	if p.closed {
		p.closedMu.Unlock()
		return ErrPoolClosed
	}
	p.closedMu.Unlock()

