//!
//! Public API:
//! - `LruCache<K, V>`: The cache type.
//! - `LruCache::new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self`
//! - `get(&self, key: &K) -> Option<V>`: Returns a clone of the value if present and not expired.
//! - `insert(&self, key: K, value: V)`: Inserts or updates a key-value pair, resetting TTL.
//! - `remove(&self, key: &K) -> Option<V>`: Removes and returns the value if present.
//! - `len(&self) -> usize`: Returns the number of non-expired entries.
//! - `Clock` trait: Injectable clock for deterministic testing.
//! - `SystemClock`: Default clock using `std::time::Instant`.
//! - `TestClock`: Deterministic clock for tests.
//!
//! Concurrency: All operations are protected by a single `Mutex`. The cache is shared via `Arc`.
//! LRU: Least Recently Used eviction. Access via `get` or `insert` marks as recently used.
//! TTL: Entries expire after `ttl` duration from their last insertion/update. Expired entries are
//!       lazily removed on access or during eviction.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Trait for injectable clock.
pub trait Clock: Send + Sync {
    fn now(&self) -> Instant;
}

/// System clock using `std::time::Instant`.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// Deterministic clock for tests.
pub struct TestClock {
    inner: Mutex<Instant>,
}

impl TestClock {
    pub fn new(start: Instant) -> Self {
        TestClock {
            inner: Mutex::new(start),
        }
    }

    pub fn advance(&self, duration: Duration) {
        let mut now = self.inner.lock().unwrap();
        *now += duration;
    }
}

impl Clock for TestClock {
    fn now(&self) -> Instant {
        *self.inner.lock().unwrap()
    }
}

