    V: Clone,
{
    fn new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self {
        CacheState {
            map: HashMap::new(),
            lru_order: Vec::new(),
            capacity,
            ttl,
            clock,
        }
    }

    /// Remove expired entries from the map and lru_order.
    fn purge_expired(&mut self) {
        let now = self.clock.now();
        let expired_keys: Vec<K> = self
            .map
            .iter()
            .filter(|(_, entry)| entry.expires_at <= now)
            .map(|(k, _)| k.clone())
            .collect();

        for key in expired_keys {
            self.map.remove(&key);
            if let Some(pos) = self.lru_order.iter().position(|k| k == &key) {
                self.lru_order.remove(pos);
            }
        }
    }

    /// Mark a key as recently used.
    fn touch(&mut self, key: &K) {
        if let Some(pos) = self.lru_order.iter().position(|k| k == key) {
            self.lru_order.remove(pos);
        }
        self.lru_order.push(key.clone());
    }

    /// Evict the least recently used entry if capacity is exceeded.
    fn evict_if_needed(&mut self) {
        while self.map.len() > self.capacity {
            if let Some(lru_key) = self.lru_order.first().cloned() {
                self.map.remove(&lru_key);
                self.lru_order.remove(0);
            } else {
                break;
            }
        }
    }

    fn get(&mut self, key: &K) -> Option<V> {
        self.purge_expired();
        if let Some(entry) = self.map.get(key) {
            let now = self.clock.now();
            if entry.expires_at > now {
                self.touch(key);
                return Some(entry.value.clone());
            } else {
                // Expired, remove it
                self.map.remove(key);
                if let Some(pos) = self.lru_order.iter().position(|k| k == key) {
                    self.lru_order.remove(pos);
                }
            }
        }
        None
    }

    fn insert(&mut self, key: K, value: V) {
        self.purge_expired();
        let now = self.clock.now();
        let expires_at = now + self.ttl;

        // If key exists, update value and expiration, and touch.
        if self.map.contains_key(&key) {
            self.map.insert(key.clone(), Entry { value, expires_at });
            self.touch(&key);
        } else {
            // New key: insert and add to LRU order.
            self.map.insert(key.clone(), Entry { value, expires_at });
            self.lru_order.push(key.clone());
            self.evict_if_needed();
        }
    }

    fn remove(&mut self, key: &K) -> Option<V> {
        self.purge_expired();
        if let Some(entry) = self.map.remove(key) {
            if let Some(pos) = self.lru_order.iter().position(|k| k == key) {
                self.lru_order.remove(pos);
            }
            Some(entry.value)
        } else {
            None
        }
    }

    fn len(&self) -> usize {
        // Note: This does not purge expired entries to avoid side effects.
        // For accurate count, we should check expiration.
        let now = self.clock.now();
        self.map
            .values()
            .filter(|entry| entry.expires_at > now)
            .count()
    }
}

