//! Bounded thread-safe LRU cache with TTL.
//!
//! Public API:
//! - `LruCache<K, V>`: The cache type.
//! - `LruCache::new(capacity: usize, clock: Arc<dyn Clock>)`: Create a new cache with given capacity and clock.
//! - `LruCache::get(&self, key: &K) -> Option<V>`: Get a value if present and not expired.
//! - `LruCache::insert(&self, key: K, value: V, ttl: Duration)`: Insert or update a key-value pair with TTL.
//! - `LruCache::remove(&self, key: &K) -> Option<V>`: Remove a key and return its value if present.
//! - `LruCache::len(&self) -> usize`: Return the number of non-expired entries.
//! - `Clock`: Trait for injectable clock.
//! - `SystemClock`: Default clock using std::time::Instant.
//! - `MockClock`: Deterministic clock for tests.
//!
//! Concurrency: All operations are thread-safe via Arc<Mutex<...>>.
//! Ownership: Keys and values are owned by the cache. Arc is used for shared access.
//! Edge cases: Zero capacity means no entries can be stored. Negative capacity is not possible (usize).
//! Eviction: When capacity is reached, the least recently used entry is evicted.
//! TTL: Entries expire after their TTL duration from insertion time.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Trait for a clock that can be injected for testing.
pub trait Clock: Send + Sync {
    /// Returns the current time as an Instant.
    fn now(&self) -> Instant;
}

/// Default clock using std::time::Instant.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// Mock clock for deterministic tests.
pub struct MockClock {
    inner: Mutex<Instant>,
}

impl MockClock {
    /// Create a new MockClock starting at the given instant.
    pub fn new(start: Instant) -> Self {
        MockClock {
            inner: Mutex::new(start),
        }
    }

    /// Advance the clock by the given duration.
    pub fn advance(&self, duration: Duration) {
        let mut guard = self.inner.lock().unwrap();
        *guard += duration;
    }
}

impl Clock for MockClock {
    fn now(&self) -> Instant {
        let guard = self.inner.lock().unwrap();
        *guard
    }
}

/// Internal entry stored in the cache.
struct Entry<V> {
    value: V,
    expires_at: Instant,
    /// Position in the LRU list (index into the order vector).
    lru_index: usize,
}

/// Internal LRU order tracking.
struct LruOrder {
    /// Vector of keys in LRU order: front = least recently used, back = most recently used.
    order: Vec<String>,
    /// Map from key to its index in the order vector.
    index_map: HashMap<String, usize>,
}

impl LruOrder {
    fn new() -> Self {
        LruOrder {
            order: Vec::new(),
            index_map: HashMap::new(),
        }
    }

    /// Mark a key as most recently used. If it exists, move it to the back.
    fn touch(&mut self, key: &str) {
        if let Some(&idx) = self.index_map.get(key) {
            // Remove from current position
            self.order.remove(idx);
            // Update indices for all elements after the removed one
            for i in idx..self.order.len() {
                let k = &self.order[i];
                self.index_map.insert(k.clone(), i);
            }
        }
        // Add to back
        let new_idx = self.order.len();
        self.order.push(key.to_string());
        self.index_map.insert(key.to_string(), new_idx);
    }

    /// Remove a key from the order. Returns true if it was present.
    fn remove(&mut self, key: &str) -> bool {
        if let Some(&idx) = self.index_map.get(key) {
            self.order.remove(idx);
            self.index_map.remove(key);
            // Update indices for all elements after the removed one
            for i in idx..self.order.len() {
                let k = &self.order[i];
                self.index_map.insert(k.clone(), i);
            }
            true
        } else {
            false
        }
    }

    /// Get the least recently used key (front of the order).
    fn lru_key(&self) -> Option<&str> {
        self.order.first().map(|s| s.as_str())
    }

    /// Get the number of entries in the order.
    fn len(&self) -> usize {
        self.order.len()
    }

    /// Check if a key is in the order.
    fn contains(&self, key: &str) -> bool {
        self.index_map.contains_key(key)
    }
