// Package workerpool provides a bounded worker pool with context cancellation,
// task submission with backpressure, panic recovery, graceful shutdown, and
// deterministic result delivery.
//
// Public API:
//
//   - NewPool(capacity int, workers int) *Pool
//     Creates a new pool with the given queue capacity and number of workers.
//     capacity must be >= 0. workers must be >= 1.
//
//   - (*Pool).Submit(ctx context.Context, task func() (interface{}, error)) error
//     Submits a task to the pool. If the queue is full, Submit blocks until
//     space is available or ctx is canceled. Returns an error if the pool is
//     closed or ctx is canceled before the task is enqueued.
//
//   - (*Pool).Wait(ctx context.Context) error
//     Waits for all submitted tasks to complete. Returns an error if ctx is
//     canceled before all tasks finish.
//
//   - (*Pool).Close()
//     Initiates graceful shutdown. No new tasks can be submitted after Close
//     is called. Existing tasks in the queue will still be processed.
//     Close is idempotent.
//
//   - (*Pool).Results() <-chan Result
//     Returns a channel that receives results from completed tasks.
//     The channel is closed when all tasks have been processed and the pool
//     is fully shut down.
//
//   - Result struct
//     Contains the task's return value, error, and any panic information.
//
// Concurrency invariants:
//   - At most `workers` goroutines execute tasks concurrently.
//   - The queue holds at most `capacity` pending tasks.
//   - Submit blocks when the queue is full (backpressure).
//   - Panics in tasks are recovered and reported via Result.
//   - Close prevents new submissions but allows queued tasks to complete.
//   - Results channel is closed after all tasks complete and pool is shut down.
//   - No goroutine leaks: all worker goroutines exit after Close and queue drain.
package workerpool

import (
	"context"
	"errors"
	"sync"
)

// Result holds the outcome of a task execution.
type Result struct {
	Value   interface{}
	Err     error
	Panic   interface{}
	HasPanic bool
}

// Pool is a bounded worker pool.
type Pool struct {
	capacity int
	workers  int

	// queue is the task queue. It is a buffered channel of tasks.
	queue chan task

	// results is the output channel for completed tasks.
	results chan Result

	// closeOnce ensures Close is idempotent.
	closeOnce sync.Once

	// closed indicates whether the pool has been closed.
	closed bool
	closedMu sync.Mutex

	// wg tracks all worker goroutines.
	wg sync.WaitGroup

	// taskWg tracks all submitted tasks that have not yet completed.
	taskWg sync.WaitGroup

	// resultsClosed indicates whether the results channel has been closed.
	resultsClosed bool
	resultsMu     sync.Mutex
}

// task represents a unit of work to be executed by a worker.
type task struct {
	fn func() (interface{}, error)
}

// NewPool creates a new worker pool with the given queue capacity and number
// of workers. capacity must be >= 0. workers must be >= 1.
// If capacity is 0, the queue is unbuffered, meaning Submit will block until
// a worker is ready to pick up the task.
func NewPool(capacity int, workers int) *Pool {
	if capacity < 0 {
		panic("workerpool: capacity must be >= 0")
	}
	if workers < 1 {
		panic("workerpool: workers must be >= 1")
	}

	p := &Pool{
		capacity: capacity,
		workers:  workers,
		queue:    make(chan task, capacity),
		results:  make(chan Result, capacity+workers), // buffer to avoid blocking workers
	}

	// Start worker goroutines.
	for i := 0; i < workers; i++ {
		p.wg.Add(1)
		go p.worker()
	}

	return p
}

// worker is the main loop for each worker goroutine.
func (p *Pool) worker() {
	defer p.wg.Done()

	for t := range p.queue {
		p.executeTask(t)
	}
}

// executeTask runs a single task, recovering from panics, and sends the result.
func (p *Pool) executeTask(t task) {
	defer p.taskWg.Done()

	var res Result

	// Recover from panics.
	defer func() {
		if r := recover(); r != nil {
			res.HasPanic = true
			res.Panic = r
		}
		// Send result. This may block if results channel is full, but we
		// sized it to capacity+workers to minimize blocking.
		p.results <- res
	}()

	val, err := t.fn()
	res.Value = val
	res.Err = err
}

// Submit submits a task to the pool. If the queue is full, Submit blocks until
// space is available or ctx is canceled. Returns an error if the pool is closed
// or ctx is canceled before the task is enqueued.
func (p *Pool) Submit(ctx context.Context, fn func() (interface{}, error)) error {
	if fn == nil {
		return errors.New("workerpool: task function is nil")
	}

	p.closedMu.Lock()
	if p.closed {
		p.closedMu.Unlock()
		return errors.New("workerpool: pool is closed")
	}
	p.closedMu.Unlock()

	// Check if context is already canceled.
	select {
	case <-ctx.Done():
		return ctx.Err()
	default:
	}

