    value: V,
    inserted_at: Instant,
    generation: u64,
}

/// Internal state of the LRU cache.
struct CacheState<K, V> {
    map: HashMap<K, Entry<V>>,
    lru_order: VecDeque<K>,
    capacity: usize,
    ttl: Duration,
    clock: Arc<dyn Clock>,
    generation_counter: u64,
