        CacheState {
            map: HashMap::new(),
            lru_order: VecDeque::new(),
            capacity,
            ttl,
            clock,
            generation_counter: 0,
        }
    }

    /// Check if an entry is expired.
    fn is_expired(&self, entry: &Entry<V>) -> bool {
        let now = self.clock.now();
        // Handle potential overflow by checking if now >= inserted_at + ttl
        // If inserted_at + ttl overflows, treat as not expired (very long TTL)
        if let Some(expiry) = entry.inserted_at.checked_add(self.ttl) {
            now >= expiry
        } else {
            false
        }
    }

