	queue chan *taskItem

	// wg tracks all active worker goroutines.
	wg sync.WaitGroup

	// closeOnce ensures Close is idempotent.
	closeOnce sync.Once

	// closed indicates whether the pool has been closed.
	closed atomic.Bool

	// activeTasks tracks the number of tasks currently in the queue or being executed.
	// Used for Wait() to know when all tasks are done.
	activeTasks atomic.Int64

	// taskDone is a channel that signals when a task completes.
	// Wait() listens on this to know when activeTasks reaches zero.
	taskDone chan struct{}

	// taskDoneOnce ensures taskDone is closed only once.
	taskDoneOnce sync.Once

	// mu protects access to closed state checks during submission.
	mu sync.Mutex
}

// taskItem wraps a task with its result channel and context.
type taskItem struct {
	task    Task
	ctx     context.Context
	result  chan Result
	canceled bool
}

// NewPool creates a new bounded worker pool.
// workers must be >= 1. queueSize must be >= 0.
// If workers < 1, it defaults to 1. If queueSize < 0, it defaults to 0.
func NewPool(workers, queueSize int) *Pool {
	if workers < 1 {
		workers = 1
	}
	if queueSize < 0 {
		queueSize = 0
	}

	p := &Pool{
		workers:   workers,
		queueSize: queueSize,
		queue:     make(chan *taskItem, queueSize),
		taskDone:  make(chan struct{}),
	}

	// Start worker goroutines.
	p.wg.Add(workers)
	for i := 0; i < workers; i++ {
