    // We use a Vec for simplicity; for large caches a linked list would be better,
    // but this is acceptable for correctness-focused implementation.
    order: Vec<K>,
    clock: Arc<dyn Clock>,
    ttl: Duration,
}

impl<K: Clone + Eq + std::hash::Hash, V: Clone> LruCacheInner<K, V> {
