//! Bounded thread-safe LRU cache with TTL.
//!
//! Public API:
//! - `LruCache<K, V>`: The cache type.
//! - `LruCache::new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self`
//! - `get(&self, key: &K) -> Option<V>`: Returns a clone of the value if present and not expired.
//! - `insert(&self, key: K, value: V)`: Inserts or updates a key-value pair, evicting LRU if at capacity.
//! - `remove(&self, key: &K) -> Option<V>`: Removes and returns the value if present.
//! - `len(&self) -> usize`: Returns the number of non-expired entries.
//! - `Clock` trait: Injectable clock for deterministic testing.
//! - `SystemClock`: Default clock using `std::time::Instant`.
//! - `TestClock`: Deterministic clock for tests.
//!
//! Concurrency: All public methods acquire a `Mutex` lock. The cache is wrapped in `Arc` for shared access.
//! LRU order is maintained via a doubly-linked list (using indices into a Vec) and a HashMap for O(1) lookup.
//! TTL is checked on `get` and `len`; expired entries are lazily removed.
//! Edge cases:
//! - Zero capacity: `insert` is a no-op; `get`/`remove` return `None`; `len` returns 0.
//! - Negative capacity is not possible (usize).
//! - Repeated close: Not applicable (no explicit close).
//! - Loader/task failures: Not applicable (no loader).
//! - Canceled waiters: Not applicable (no async).
//! - Resources released during cleanup: Entries are dropped when evicted or removed.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Trait for an injectable clock.
pub trait Clock: Send + Sync {
    /// Returns the current time as a `Duration` since some arbitrary epoch.
    fn now(&self) -> Duration;
}

/// Default clock using `std::time::Instant`.
pub struct SystemClock {
    start: Instant,
}

impl SystemClock {
    pub fn new() -> Self {
        SystemClock {
            start: Instant::now(),
        }
    }
}

impl Default for SystemClock {
    fn default() -> Self {
        Self::new()
    }
}

impl Clock for SystemClock {
    fn now(&self) -> Duration {
        self.start.elapsed()
    }
}

/// Deterministic clock for tests.
pub struct TestClock {
    time: Mutex<Duration>,
}

impl TestClock {
    pub fn new() -> Self {
        TestClock {
            time: Mutex::new(Duration::from_secs(0)),
        }
    }

    /// Advance the clock by the given duration.
    pub fn advance(&self, duration: Duration) {
        let mut t = self.time.lock().unwrap();
        *t += duration;
    }

    /// Set the clock to a specific duration.
    pub fn set(&self, duration: Duration) {
        let mut t = self.time.lock().unwrap();
        *t = duration;
    }
}

impl Default for TestClock {
    fn default() -> Self {
        Self::new()
    }
}

impl Clock for TestClock {
    fn now(&self) -> Duration {
        let t = self.time.lock().unwrap();
        *t
    }
}

