// Pool is a bounded worker pool with context cancellation, backpressure,
// panic recovery, graceful shutdown, and deterministic result delivery.
//
// Public API:
//   - NewPool(capacity int) *Pool: Creates a new pool with the given worker capacity.
//     Capacity must be positive. Zero or negative capacity returns an error.
//   - Submit(ctx context.Context, task Task) (<-chan Result, error): Submits a task.
//     Returns a channel that will receive exactly one Result. If the pool is full,
//     it blocks until a worker is available or ctx is canceled. Returns error if
//     the pool is closed or ctx is canceled before submission.
//   - Shutdown(ctx context.Context) error: Gracefully shuts down the pool.
//     Stops accepting new tasks, waits for in-flight tasks to complete (or ctx canceled),
//     and releases all resources. Returns error if ctx is canceled during shutdown.
//   - Close(): Immediately closes the pool, canceling all in-flight tasks and
//     releasing resources. Safe to call multiple times.
//
// Concurrency invariants:
//   - At most `capacity` tasks are executing concurrently.
//   - Each submitted task receives exactly one Result on its result channel.
//   - Panics in tasks are recovered and converted to errors in Result.
//   - No goroutine leaks: all worker goroutines exit when the pool is closed.
//   - No data races: all shared state is protected by mutexes or atomic operations.
type Pool struct {
	capacity   int
	tasks      chan taskEnvelope
	workers    sync.WaitGroup
	closed     atomic.Bool
	closeOnce  sync.Once
	mu         sync.Mutex
	inFlight   int
	inFlightCond *sync.Cond
}

type taskEnvelope struct {
	ctx    context.Context
	task   Task
	result chan Result
}

// NewPool creates a new worker pool with the given capacity.
// Capacity must be a positive integer. Returns nil and an error if capacity <= 0.
func NewPool(capacity int) (*Pool, error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("worker pool capacity must be positive, got %d", capacity)
	}
	p := &Pool{
		capacity: capacity,
		tasks:    make(chan taskEnvelope, capacity),
	}
	p.inFlightCond = sync.NewCond(&p.mu)
	return p, nil
}

// Submit submits a task to the pool. It returns a channel that will receive
// exactly one Result. If the pool is full, Submit blocks until a worker is
// available or ctx is canceled. Returns an error if the pool is closed or
// ctx is canceled before the task is accepted.
func (p *Pool) Submit(ctx context.Context, task Task) (<-chan Result, error) {
	if p.closed.Load() {
		return nil, errors.New("pool is closed")
	}
	if task == nil {
		return nil, errors.New("task cannot be nil")
	}

	result := make(chan Result, 1)
	env := taskEnvelope{
		ctx:    ctx,
		task:   task,
		result: result,
	}

	// Check if we can submit without blocking (pool not full)
	select {
	case p.tasks <- env:
		// Successfully queued
		return result, nil
	default:
		// Pool is full, need to wait
	}

	// Pool is full, wait for space or cancellation
	p.mu.Lock()
	for p.inFlight >= p.capacity && !p.closed.Load() {
		// Wait for a worker to finish or pool to close
		p.inFlightCond.Wait()
	}
	if p.closed.Load() {
		p.mu.Unlock()
		return nil, errors.New("pool is closed")
	}
	// We have space now, increment inFlight and try to send
	p.inFlight++
	p.mu.Unlock()

	// Now send to the channel. Since we reserved a slot, this should not block
	// unless there's a race with another submitter. To handle this, we use a
	// select with context to avoid deadlock.
	select {
	case p.tasks <- env:
		return result, nil
	case <-ctx.Done():
		// Context canceled while waiting to send. Decrement inFlight.
		p.mu.Lock()
		p.inFlight--
		p.inFlightCond.Signal()
		p.mu.Unlock()
		return nil, ctx.Err()
	}
}

// Shutdown gracefully shuts down the pool. It stops accepting new tasks,
// waits for all in-flight tasks to complete, and releases resources.
// If ctx is canceled before all tasks complete, Shutdown returns ctx.Err().
func (p *Pool) Shutdown(ctx context.Context) error {
	// Mark as closed to prevent new submissions
	p.closed.Store(true)

	// Close the tasks channel to signal workers to stop accepting new tasks
	// But we need to let in-flight tasks complete first.
	// We'll use a separate mechanism: workers check closed flag.

	// Wait for all workers to finish
	done := make(chan struct{})
	go func() {
		p.workers.Wait()
		close(done)
	}()

	select {
	case <-done:
		return nil
	case <-ctx.Done():
		// Force close if context is canceled
		p.Close()
		return ctx.Err()
	}
}

// Close immediately closes the pool, canceling all in-flight tasks and
// releasing resources. Safe to call multiple times.
func (p *Pool) Close() {
	p.closeOnce.Do(func() {
		p.closed.Store(true)
		// Close the tasks channel to unblock any waiting submitters
		close(p.tasks)
		// Signal all waiting submitters
		p.mu.Lock()
		p.inFlightCond.Broadcast()
		p.mu.Unlock()
	})
}

// startWorkers starts the worker goroutines. This is called lazily on first submit.
func (p *Pool) startWorkers() {
	p.mu.Lock()
	if p.workersStarted {
		p.mu.Unlock()
		return
	}
	p.workersStarted = true
	p.mu.Unlock()

	for i := 0; i < p.capacity; i++ {
		p.workers.Add(1)
		go p.worker()
	}
