use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::Instant;

/// Trait for providing current time, enabling deterministic testing.
pub trait Clock: Send + Sync {
    fn now(&self) -> Instant;
}

/// System clock using std::time::Instant.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// Deterministic clock for tests. Allows setting time explicitly.
pub struct TestClock {
    time: Mutex<Instant>,
}

impl TestClock {
    /// Create a new TestClock with a given base instant.
    pub fn new(base: Instant) -> Self {
        TestClock {
            time: Mutex::new(base),
        }
    }

    /// Set the current time of the clock.
    pub fn set_time(&self, t: Instant) {
        let mut guard = self.time.lock().unwrap();
        *guard = t;
    }

    /// Advance the clock by a duration.
    pub fn advance(&self, dur: std::time::Duration) {
        let mut guard = self.time.lock().unwrap();
        *guard += dur;
    }
}

impl Clock for TestClock {
    fn now(&self) -> Instant {
        let guard = self.time.lock().unwrap();
        *guard
    }
}

