import (
	"context"
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
)

// Task represents a unit of work to be executed by the worker pool.
// The Task function receives a context that is canceled when the pool is shutting down
// or when the task's deadline/context is canceled.
type Task func(ctx context.Context) (interface{}, error)

// Result represents the outcome of a task execution.
type Result struct {
	Value interface{}
	Err   error
}

// Pool is a bounded worker pool with context cancellation, backpressure,
// panic recovery, graceful shutdown, and deterministic result delivery.
//
// Public API:
//   - NewPool(capacity int) *Pool: Creates a new pool with the given worker capacity.
//     Capacity must be positive. Zero or negative capacity returns an error.
//   - Submit(ctx context.Context, task Task) (<-chan Result, error): Submits a task to the pool.
//     Returns a channel that will receive exactly one Result when the task completes,
//     or an error if the pool is closed or the context is canceled before submission.
//     Backpressure: if all workers are busy and the queue is full, Submit blocks until
//     a slot is available or the context is canceled.
//   - Shutdown(ctx context.Context) error: Initiates graceful shutdown. No new tasks are accepted.
//     Waits for all in-flight tasks to complete or until the context is canceled.
//     Returns an error if the context is canceled before all tasks complete.
//   - Close(): Immediately closes the pool, canceling all in-flight tasks and rejecting new submissions.
//     Does not wait for in-flight tasks to complete.
//
// Concurrency invariants:
//   - At most `capacity` tasks are executing concurrently.
//   - Each submitted task produces exactly one Result on its result channel.
//   - Panics in tasks are recovered and converted to errors in the Result.
//   - No goroutine leaks: all worker goroutines exit when the pool is closed.
//   - No data races: all shared state is protected by mutexes or atomic operations.
type Pool struct {
	capacity   int
	queue      chan *taskEntry
	workers    sync.WaitGroup
	closed     atomic.Bool
	closeOnce  sync.Once
	closeCh    chan struct{}
	mu         sync.Mutex
	inFlight   int
	inFlightCond *sync.Cond
}

type taskEntry struct {
	ctx    context.Context
	task   Task
	result chan Result
}

// NewPool creates a new worker pool with the given capacity.
// Capacity must be a positive integer. Returns an error if capacity <= 0.
func NewPool(capacity int) (*Pool, error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("worker pool capacity must be positive, got %d", capacity)
	}
	p := &Pool{
		capacity: capacity,
		queue:    make(chan *taskEntry, capacity),
		closeCh:  make(chan struct{}),
	}
	p.inFlightCond = sync.NewCond(&p.mu)
	return p, nil
}

// Submit submits a task to the pool. It returns a channel that will receive exactly one
// Result when the task completes. If the pool is closed or the context is canceled before
// the task is accepted, an error is returned and the result channel is closed.
//
// Backpressure: if all workers are busy and the internal queue is full, Submit blocks
// until a slot becomes available or the context is canceled.
func (p *Pool) Submit(ctx context.Context, task Task) (<-chan Result, error) {
	if p.closed.Load() {
		return nil, errors.New("pool is closed")
	}

	// Check if context is already canceled
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
	}

	resultCh := make(chan Result, 1)
	entry := &taskEntry{
		ctx:    ctx,
		task:   task,
		result: resultCh,
	}

	// Try to enqueue with backpressure
	select {
	case p.queue <- entry:
		// Successfully enqueued
		return resultCh, nil
	case <-ctx.Done():
		return nil, ctx.Err()
	case <-p.closeCh:
		return nil, errors.New("pool is closed")
	}
}

// Shutdown initiates graceful shutdown. No new tasks are accepted after this call.
// It waits for all in-flight tasks to complete or until the provided context is canceled.
// Returns an error if the context is canceled before all tasks complete.
func (p *Pool) Shutdown(ctx context.Context) error {
	p.closed.Store(true)

	// Wait for all workers to finish processing queued and in-flight tasks
	done := make(chan struct{})
	go func() {
		p.workers.Wait()
		close(done)
	}()

	select {
	case <-done:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

// Close immediately closes the pool, canceling all in-flight tasks and rejecting new submissions.
// Does not wait for in-flight tasks to complete. Safe to call multiple times.
func (p *Pool) Close() {
	p.closeOnce.Do(func() {
		p.closed.Store(true)
		close(p.closeCh)
	})
}

// startWorkers starts the worker goroutines. This is called lazily on first submit.
// Workers process tasks from the queue until the pool is closed.
func (p *Pool) startWorkers() {
	p.mu.Lock()
	if p.workersStarted {
		p.mu.Unlock()
		return
	}
	p.workersStarted = true
	p.mu.Unlock()

	for i := 0; i < p.capacity; i++ {
		p.workers.Add(1)
		go p.worker()
	}
}

