/**
 * Strongly typed bounded asynchronous work queue.
 *
 * Public API:
 * - class AsyncWorkQueue<T, R>
 *   - constructor(options: AsyncWorkQueueOptions<T, R>)
 *   - enqueue(task: T): Promise<R>
 *   - close(): Promise<void>
 *   - get pendingCount(): number
 *   - get runningCount(): number
 *   - get capacity(): number
 *
 * Options:
 * - concurrency: number (default 1) - max concurrent running tasks
 * - capacity: number (default Infinity) - max pending + running tasks (backpressure)
 * - signal?: AbortSignal - external cancellation signal
 * - onError?: (error: unknown, task: T) => void - optional error handler
 *
 * Behavior:
 * - enqueue() returns a promise that resolves with the task result or rejects with the error.
 * - If the queue is closed, enqueue() rejects with a "Queue closed" error.
 * - If capacity is reached, enqueue() waits until space is available (backpressure).
 * - If the AbortSignal is aborted, pending tasks are rejected with an AbortError.
 * - Running tasks are not forcibly cancelled; they complete naturally.
 * - close() stops accepting new tasks, waits for running tasks to complete, and rejects pending tasks.
 * - Repeated close() calls are idempotent.
 * - Zero or negative capacity means no tasks can be enqueued (immediate rejection).
 * - Loader/task failures reject the corresponding enqueue promise.
 * - Canceled waiters (pending tasks waiting for capacity) are rejected on abort or close.
 * - Resources are released during cleanup (no lingering timers or listeners).
 */

// Type definitions

export interface AsyncWorkQueueOptions<T, R> {
  concurrency?: number;
  capacity?: number;
  signal?: AbortSignal;
  onError?: (error: unknown, task: T) => void;
}

interface PendingTask<T, R> {
  task: T;
  resolve: (value: R) => void;
  reject: (reason: unknown) => void;
  settled: boolean;
}

interface RunningTask<T, R> {
  task: T;
  promise: Promise<R>;
  settled: boolean;
}

// Custom error classes for clarity
class QueueClosedError extends Error {
  constructor() {
    super("Queue closed");
    this.name = "QueueClosedError";
  }
}

class QueueCapacityError extends Error {
  constructor() {
    super("Queue capacity exceeded");
    this.name = "QueueCapacityError";
  }
}

class AbortError extends Error {
  constructor() {
    super("Aborted");
    this.name = "AbortError";
  }
}

