use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// A thread-safe LRU cache with TTL support.
///
/// # Public API
/// - `new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self`
/// - `get(&self, key: &K) -> Option<V>`
/// - `insert(&self, key: K, value: V)`
/// - `remove(&self, key: &K) -> Option<V>`
/// - `len(&self) -> usize`
///
/// # Ownership Choices
/// - `Arc<Mutex<CacheInner<K, V>>>` wraps the internal state for safe shared access across threads.
/// - `Clock` is an injectable trait for deterministic testing of TTL behavior.
/// - `LRU` uses a doubly-linked list implemented via indices into a `Vec` of nodes, avoiding unsafe code.
/// - Keys and values are owned by the cache; `get` returns a clone of the value (requires `Clone`).
/// - `remove` returns the owned value if present.

/// Trait for an injectable clock, enabling deterministic TTL tests.
pub trait Clock: Send + Sync {
    fn now(&self) -> Instant;
}

/// A real-time clock implementation.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// A mock clock for testing, allowing manual time advancement.
pub struct MockClock {
    time: Mutex<Instant>,
}

