    pub fn new(start: Instant) -> Self {
        MockClock {
            time: Mutex::new(start),
        }
    }

    pub fn advance(&self, duration: Duration) {
        let mut time = self.time.lock().unwrap();
        *time += duration;
    }
}

impl Clock for MockClock {
    fn now(&self) -> Instant {
        let time = self.time.lock().unwrap();
        *time
    }
}

