// Package workerpool implements a bounded worker pool with context cancellation,
// task submission with backpressure, panic recovery, graceful shutdown, and
// deterministic result delivery.
//
// Public API:
//
//   - NewPool(capacity int, workers int) *Pool
//     Creates a new pool with the given queue capacity and number of workers.
//     capacity must be >= 0; workers must be >= 1.
//
//   - (*Pool).Submit(ctx context.Context, task func() (interface{}, error)) error
//     Submits a task to the pool. Blocks if the queue is full (backpressure).
//     Returns an error if the pool is closed, the context is canceled, or the
//     queue is full and the context is canceled while waiting.
//     The task is executed by a worker; its result and error are delivered via
//     the returned Future.
//
//   - (*Pool).Shutdown(ctx context.Context) error
//     Initiates graceful shutdown. No new tasks are accepted. Existing tasks
//     in the queue are processed. Returns when all workers have finished or
//     the context is canceled.
//
//   - (*Pool).Close()
//     Forces immediate shutdown. All pending tasks are discarded. Workers
//     stop as soon as possible. Safe to call multiple times.
//
//   - Future
//     Represents the result of a submitted task.
//     - (*Future).Result(ctx context.Context) (interface{}, error)
//       Blocks until the task completes or the context is canceled.
//       Returns the task's result and error, or an error if the context is
//       canceled or the task panicked.
//     - (*Future).Cancel()
//       Attempts to cancel the task. If the task has not started, it is
//       removed from the queue. If it has started, cancellation is best-effort.
//
// Concurrency invariants:
//   - At most `workers` goroutines execute tasks concurrently.
//   - The queue never exceeds `capacity` items.
//   - All goroutines are properly cleaned up on Close/Shutdown.
//   - No data races on shared state.
package workerpool

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
)

// ErrPoolClosed is returned when submitting to a closed pool.
var ErrPoolClosed = errors.New("workerpool: pool is closed")

// ErrQueueFull is returned when the queue is full and cannot accept more tasks.
var ErrQueueFull = errors.New("workerpool: queue is full")

// ErrTaskCanceled is returned when a task is canceled before execution.
var ErrTaskCanceled = errors.New("workerpool: task canceled")

// ErrPanic is returned when a task panics.
var ErrPanic = errors.New("workerpool: task panicked")

// Future represents the result of a submitted task.
type Future struct {
	mu       sync.Mutex
	done     chan struct{}
	result   interface{}
	err      error
	canceled bool
	started  bool
}

// Result blocks until the task completes or the context is canceled.
// Returns the task's result and error, or an error if the context is canceled
// or the task panicked.
func (f *Future) Result(ctx context.Context) (interface{}, error) {
	select {
	case <-f.done:
		f.mu.Lock()
		defer f.mu.Unlock()
		return f.result, f.err
	case <-ctx.Done():
		return nil, ctx.Err()
	}
}

// Cancel attempts to cancel the task. If the task has not started, it is
// removed from the queue. If it has started, cancellation is best-effort.
func (f *Future) Cancel() {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.canceled {
		return
	}
	f.canceled = true
	if !f.started {
		// Mark as done with canceled error
		f.err = ErrTaskCanceled
		close(f.done)
	}
}

// isCanceled returns whether the future has been canceled.
func (f *Future) isCanceled() bool {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.canceled
}

// isStarted returns whether the task has started execution.
func (f *Future) isStarted() bool {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.started
}

// markStarted marks the task as started.
func (f *Future) markStarted() {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.started = true
}

// setDone sets the result and error, and signals completion.
func (f *Future) setDone(result interface{}, err error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.canceled {
		// Already canceled, don't overwrite
		return
	}
	f.result = result
	f.err = err
	close(f.done)
}

// task represents a unit of work to be executed by a worker.
type task struct {
	fn     func() (interface{}, error)
	future *Future
}

// Pool is a bounded worker pool.
type Pool struct {
	capacity int
	workers  int

	queue      chan *task
	queueMu    sync.Mutex
	queueClosed bool

	workerWg   sync.WaitGroup
	closeOnce  sync.Once
	closed     atomic.Bool
	shutdownCh chan struct{}
}

// NewPool creates a new pool with the given queue capacity and number of workers.
// capacity must be >= 0; workers must be >= 1.
func NewPool(capacity int, workers int) *Pool {
	if capacity < 0 {
		capacity = 0
	}
	if workers < 1 {
		workers = 1
	}

	p := &Pool{
		capacity:   capacity,
		workers:    workers,
		queue:      make(chan *task, capacity),
		shutdownCh: make(chan struct{}),
	}

	// Start workers
	p.workerWg.Add(workers)
	for i := 0; i < workers; i++ {
		go p.worker()
	}

	return p
}

// worker is the main loop for a worker goroutine.
func (p *Pool) worker() {
	defer p.workerWg.Done()

	for {
		select {
		case <-p.shutdownCh:
			// Drain remaining tasks in the queue before exiting
			for {
				select {
				case t := <-p.queue:
					p.executeTask(t)
				default:
					return
				}
			}
		case t, ok := <-p.queue:
			if !ok {
				// Queue closed, exit
				return
			}
			p.executeTask(t)
		}
	}
}

