/**
 * Strongly typed bounded asynchronous work queue.
 *
 * Public API:
 * - class AsyncWorkQueue<T, R>
 *   - constructor(options: AsyncWorkQueueOptions<T, R>)
 *   - enqueue(task: T): Promise<R>
 *   - close(): Promise<void>
 *   - get pendingCount(): number
 *   - get runningCount(): number
 *   - get capacity(): number
 *
 * Options:
 * - concurrency: number (default 1) - max concurrent running tasks
 * - capacity: number (default Infinity) - max pending + running tasks (backpressure)
 * - signal?: AbortSignal - external cancellation signal
 * - onError?: (error: unknown, task: T) => void - optional error handler
 *
 * Behavior:
 * - enqueue() returns a Promise that resolves with the task result or rejects with the error.
 * - If the queue is closed, enqueue() rejects with a "Queue is closed" error.
 * - If capacity is reached, enqueue() waits until space is available (backpressure).
 * - If capacity is 0 or negative, enqueue() rejects immediately with a capacity error.
 * - AbortSignal cancellation:
 *   - Pending tasks (not yet started) are canceled and their promises reject with AbortError.
 *   - Running tasks are NOT canceled by the signal; they continue to completion.
 *   - After cancellation, no new tasks are started.
 * - close():
 *   - Stops accepting new tasks.
 *   - Waits for all running tasks to complete.
 *   - Rejects all pending tasks with a "Queue is closed" error.
 *   - Resolves when all running tasks have finished.
 * - Repeated close() calls are idempotent.
 * - Loader/task failures are propagated to the enqueue() promise.
 * - Canceled waiters (tasks waiting for capacity) are rejected when the queue is closed or aborted.
 * - Resources are released during cleanup.
 */

import { test } from 'node:test';
import assert from 'node:assert';

// Type definitions

export interface AsyncWorkQueueOptions<T, R> {
  concurrency?: number;
  capacity?: number;
  signal?: AbortSignal;
  onError?: (error: unknown, task: T) => void;
}

interface TaskEntry<T, R> {
  task: T;
  resolve: (value: R) => void;
  reject: (reason: unknown) => void;
  promise: Promise<R>;
  canceled: boolean;
}

export class AsyncWorkQueue<T, R> {
  private readonly concurrency: number;
  private readonly capacity: number;
  private readonly signal?: AbortSignal;
  private readonly onError?: (error: unknown, task: T) => void;

  private pending: TaskEntry<T, R>[] = [];
  private runningCount: number = 0;
  private closed: boolean = false;
  private aborted: boolean = false;
  private closePromise: Promise<void> | null = null;
  private closeResolve: (() => void) | null = null;
  private closeReject: ((reason: unknown) => void) | null = null;

  // Waiters for capacity: when a task is waiting for space, we store its resolve/reject
  private capacityWaiters: Array<{
    resolve: () => void;
    reject: (reason: unknown) => void;
    canceled: boolean;
  }> = [];

  constructor(options: AsyncWorkQueueOptions<T, R> = {}) {
    this.concurrency = options.concurrency ?? 1;
    this.capacity = options.capacity ?? Infinity;
    this.signal = options.signal;
    this.onError = options.onError;

    if (this.concurrency < 1) {
      throw new Error('concurrency must be at least 1');
    }

    if (this.signal) {
      if (this.signal.aborted) {
        this.aborted = true;
      } else {
        this.signal.addEventListener('abort', () => {
          this.handleAbort();
        });
      }
    }
  }

  get pendingCount(): number {
    return this.pending.length;
  }

  get runningCount(): number {
    return this.runningCount;
  }

  get capacity(): number {
    return this.capacity;
  }

  /**
   * Enqueue a task. Returns a promise that resolves with the result or rejects with an error.
   * If the queue is closed, rejects immediately.
   * If capacity is 0 or negative, rejects immediately.
   * If capacity is reached, waits for space (backpressure).
   */
  enqueue(task: T): Promise<R> {
    // Check if queue is closed
    if (this.closed) {
      return Promise.reject(new Error('Queue is closed'));
    }

    // Check if aborted
    if (this.aborted) {
      return Promise.reject(new Error('Queue is aborted'));
    }

    // Check capacity: if capacity is 0 or negative, reject immediately
    if (this.capacity <= 0) {
      return Promise.reject(new Error('Queue capacity is zero or negative'));
    }

    // Check if we have space: pending + running < capacity
    // If not, wait for space
    if (this.pending.length + this.runningCount >= this.capacity) {
      return this.waitForCapacity(task);
    }

    // We have space, add to pending and try to start
    return this.addTask(task);
  }

  /**
   * Wait for capacity to become available.
   */
  private waitForCapacity(task: T): Promise<R> {
    return new Promise<R>((resolve, reject) => {
      const waiter = {
        resolve: () => {
          // When capacity becomes available, add the task
          const entry = this.addTaskInternal(task);
          entry.promise.then(resolve, reject);
        },
        reject: (reason: unknown) => {
          reject(reason);
        },
        canceled: false,
      };

      this.capacityWaiters.push(waiter);

      // If the queue is closed or aborted while waiting, reject the waiter
      if (this.closed) {
        waiter.canceled = true;
        reject(new Error('Queue is closed'));
        return;
      }
      if (this.aborted) {
        waiter.canceled = true;
        reject(new Error('Queue is aborted'));
        return;
      }
    });
  }

  /**
   * Add a task to the pending queue and try to start it.
   */
  private addTask(task: T): Promise<R> {
    const entry = this.addTaskInternal(task);
    this.tryStartTasks();
    return entry.promise;
  }

  /**
   * Internal method to create a task entry and add it to pending.
   */
  private addTaskInternal(task: T): TaskEntry<T, R

