/// Entry stored in the LRU cache.
struct CacheEntry<V> {
    value: V,
    expires_at: Instant,
}

/// A bounded thread-safe LRU cache with TTL.
///
/// Public API:
/// - `new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self`
/// - `get(&self, key: &K) -> Option<V>`
/// - `insert(&self, key: K, value: V)`
/// - `remove(&self, key: &K) -> Option<V>`
/// - `len(&self) -> usize`
///
/// All methods are safe for concurrent access via Arc<Mutex<...>>.
pub struct LruCache<K, V>
where
    K: Eq + std::hash::Hash + Clone,
    V: Clone,
{
    inner: Mutex<LruCacheInner<K, V>>,
    clock: Arc<dyn Clock>,
}

struct LruCacheInner<K, V>
where
    K: Eq + std::hash::Hash + Clone,
    V: Clone,
{
    capacity: usize,
    ttl: Duration,
    map: HashMap<K, CacheEntry<V>>,
    // LRU order: front is most recently used, back is least recently used.
    // We use a Vec for simplicity; for large caches a linked list would be better,
    // but this keeps the code simple and correct.
    lru_order: Vec<K>,
}

impl<K, V> LruCache<K, V>
where
    K: Eq + std::hash::Hash + Clone,
    V: Clone,
{
    /// Create a new LRU cache with the given capacity, TTL, and clock.
    ///
    /// If capacity is 0, the cache will not store any entries.
    /// If capacity is negative (not possible with usize), it's treated as 0.
    pub fn new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self {
        LruCache {
            inner: Mutex::new(LruCacheInner {
                capacity,
                ttl,
                map: HashMap::new(),
                lru_order: Vec::new(),
            }),
            clock,
        }
    }

    /// Get a value from the cache. Returns None if the key is not present or expired.
    /// If the entry is found and not expired, it is moved to the front of the LRU order.
    pub fn get(&self, key: &K) -> Option<V> {
        let now = self.clock.now();
        let mut inner = self.inner.lock().unwrap();

        if let Some(entry) = inner.map.get(key) {
            if entry.expires_at > now {
                // Move to front of LRU order
                inner.touch_lru(key);
                return Some(entry.value.clone());
            } else {
                // Expired: remove it
                inner.remove_entry(key);
            }
        }
        None
    }

    /// Insert a key-value pair into the cache.
    /// If the key already exists, its value and expiration are updated, and it is moved to the front.
    /// If the cache is at capacity, the least recently used entry is evicted.
    pub fn insert(&self, key: K, value: V) {
        let now = self.clock.now();
        let expires_at = now + self.inner.lock().unwrap().ttl;
        let mut inner = self.inner.lock().unwrap();

        // If capacity is 0, do not store anything.
        if inner.capacity == 0 {
            return;
        }

        // If key exists, update it and move to front.
        if inner.map.contains_key(&key) {
            inner.map.insert(
                key.clone(),
                CacheEntry {
                    value,
                    expires_at,
                },
            );
            inner.touch_lru(&key);
            return;
        }

        // If at capacity, evict LRU entry.
        if inner.map.len() >= inner.capacity {
            if let Some(lru_key) = inner.lru_order.last().cloned() {
                inner.remove_entry(&lru_key);
            }
        }

        // Insert new entry.
        inner.map.insert(
            key.clone(),
            CacheEntry {
                value,
                expires_at,
            },
        );
        inner.lru_order.insert(0, key);
    }

    /// Remove a key from the cache. Returns the value if it was present and not expired.
    pub fn remove(&self, key: &K) -> Option<V> {
        let now = self.clock.now();
        let mut inner = self.inner.lock().unwrap();

        if let Some(entry) = inner.map.get(key) {
            if entry.expires_at > now {
