package workerpool

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

// Task represents a unit of work to be executed by the worker pool.
// The task receives a context that is canceled when the pool is shutting down
// or when the task's deadline expires.
type Task func(ctx context.Context) (interface{}, error)

// Result holds the outcome of a task execution.
type Result struct {
	Value interface{}
	Err   error
}

// Pool is a bounded worker pool with context cancellation, backpressure,
// panic recovery, graceful shutdown, and deterministic result delivery.
//
// Public API:
//   - NewPool(capacity int) *Pool: creates a pool with the given worker capacity.
//     Capacity must be positive.
//   - Submit(ctx context.Context, task Task) (<-chan Result, error): submits a task
//     for execution. Returns a channel that will receive exactly one Result.
//     Returns an error if the pool is closed or if backpressure is applied and
//     the context is canceled while waiting for a slot.
//   - Shutdown(ctx context.Context) error: gracefully shuts down the pool.
//     Stops accepting new tasks, waits for in-flight tasks to complete (or
//     context cancellation), and releases all resources.
//   - Close(): immediately closes the pool, canceling all in-flight tasks.
//
// Concurrency invariants:
//   - At most `capacity` tasks execute concurrently.
//   - Each submitted task produces exactly one Result on its result channel.
//   - Panics in tasks are recovered and converted to errors.
//   - No goroutine leaks: all worker goroutines exit after Shutdown/Close.
//   - No data races: all shared state is protected by mutexes or atomics.
type Pool struct {
	capacity   int
	tasks      chan taskEnvelope
	workers    sync.WaitGroup
	closeOnce  sync.Once
	closed     atomic.Bool
	shutdownCh chan struct{}
	mu         sync.Mutex
	inFlight   int
}

type taskEnvelope struct {
	ctx    context.Context
	task   Task
	result chan Result
}

// NewPool creates a new worker pool with the given capacity.
// Capacity must be a positive integer.
func NewPool(capacity int) *Pool {
	if capacity <= 0 {
		panic("workerpool: capacity must be positive")
	}
	p := &Pool{
		capacity:   capacity,
		tasks:      make(chan taskEnvelope, capacity),
		shutdownCh: make(chan struct{}),
	}
	// Start worker goroutines
	for i := 0; i < capacity; i++ {
		p.workers.Add(1)
		go p.worker()
	}
	return p
}

// worker is the main loop for each worker goroutine.
func (p *Pool) worker() {
	defer p.workers.Done()
	for {
		select {
		case <-p.shutdownCh:
			// Drain any remaining tasks in the queue before exiting.
			// This ensures all submitted tasks get a result.
			for {
				select {
				case env := <-p.tasks:
					p.executeTask(env)
				default:
					return
				}
			}
		case env := <-p.tasks:
			p.executeTask(env)
		}
	}
}

// executeTask runs a single task with panic recovery and context handling.
func (p *Pool) executeTask(env taskEnvelope) {
	defer func() {
		if r := recover(); r != nil {
			env.result <- Result{
				Value: nil,
				Err:   fmt.Errorf("panic in task: %v", r),
			}
		}
	}()

	// Check if the task's context is already canceled
	select {
	case <-env.ctx.Done():
		env.result <- Result{
			Value: nil,
			Err:   env.ctx.Err(),
		}
		return
	default:
	}

	// Execute the task
	value, err := env.task(env.ctx)
	env.result <- Result{
		Value: value,
		Err:   err,
	}
}

// Submit submits a task for execution. It returns a channel that will receive
// exactly one Result. If the pool is closed, it returns an error. If the
// context is canceled while waiting for a slot, it returns an error.
func (p *Pool) Submit(ctx context.Context, task Task) (<-chan Result, error) {
	if p.closed.Load() {
		return nil, errors.New("workerpool: pool is closed")
	}

	result := make(chan Result, 1)
	env := taskEnvelope{
		ctx:    ctx,
		task:   task,
		result: result,
	}

	// Try to submit with backpressure: if the queue is full, wait for a slot
	// or context cancellation.
	select {
	case p.tasks <- env:
		return result, nil
	case <-ctx.Done():
		return nil, ctx.Err()
	case <-p.shutdownCh:
		return nil, errors.New("workerpool: pool is shutting down")
	}
}

// Shutdown gracefully shuts down the pool. It stops accepting new tasks,
// waits for in-flight tasks to complete (or context cancellation), and
// releases all resources.
func (p *Pool) Shutdown(ctx context.Context) error {
	p.closeOnce.Do(func() {
		p.closed.Store(true)
		close(p.shutdownCh)
	})

	// Wait for all workers to finish, respecting context cancellation.
	done := make(chan struct{})
	go func() {
		p.workers.Wait()
		close(done)
	}()

	select {
	case <-done:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

// Close immediately closes the pool, canceling all in-flight tasks.
// It is safe to call multiple times.
func (p *Pool) Close() {
	p.closeOnce.Do(func() {
		p.closed.Store(true)
		close(p.shutdownCh)
	})
	// Wait for workers to exit to avoid goroutine leaks.
	p.workers.Wait()
}
